            JavaScript

    class TicTacToe {
  constructor() {
    this.board = Array.from({ length: 3 }, () => Array(3).fill(" "));
    this.currentPlayer = 1; // 1 = Player 1, 2 = Player 2
  }

  printBoard() {
    for (let i = 0; i < 3; i++) {
      console.log(this.board[i].join(" | "));
      if (i < 2) console.log("---------");
    }
  }

  isBoardFull() {
    return this.board.every(row => row.every(cell => cell !== " "));
  }

  makeMove(row, col) {
    if (
      row < 0 || row >= 3 ||
      col < 0 || col >= 3 ||
      this.board[row][col] !== " "
    ) {
      return false;
    }
    this.board[row][col] = this.currentPlayer === 1 ? "X" : "O";
    this.currentPlayer = 3 - this.currentPlayer; // switch player
    return true;
  }

  checkWinner() {
    // Rows & Columns
    for (let i = 0; i < 3; i++) {
      if (
        this.board[i][0] !== " " &&
        this.board[i][0] === this.board[i][1] &&
        this.board[i][1] === this.board[i][2]
      ) return true;

      if (
        this.board[0][i] !== " " &&
        this.board[0][i] === this.board[1][i] &&
        this.board[1][i] === this.board[2][i]
      ) return true;
    }
    // Diagonals
    if (
      this.board[0][0] !== " " &&
      this.board[0][0] === this.board[1][1] &&
      this.board[1][1] === this.board[2][2]
    ) return true;

    if (
      this.board[0][2] !== " " &&
      this.board[0][2] === this.board[1][1] &&
      this.board[1][1] === this.board[2][0]
    ) return true;

    return false;
  }

  getCurrentPlayer() {
    return this.currentPlayer;
  }
}

// Example with readline (Node.js)
const readline = require("readline").createInterface({
  input: process.stdin,
  output: process.stdout
});

const game = new TicTacToe();

function playTurn() {
  if (game.isBoardFull() || game.checkWinner()) {
    game.printBoard();
    if (game.checkWinner()) {
      console.log(`Player ${3 - game.getCurrentPlayer()} wins!`);
    } else {
      console.log("It's a draw!");
    }
    readline.close();
    return;
  }

  game.printBoard();
  readline.question(`Player ${game.getCurrentPlayer()}, enter row and column (e.g. "0 1"): `, input => {
    const [row, col] = input.split(" ").map(Number);
    if (game.makeMove(row, col)) {
      console.log("Move successful!\n");
    } else {
      console.log("Invalid move. Try again.\n");
    }
    playTurn();
  });
}

